import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// ---------------------------------------------------------------------------
// Platform (Packet 01)
// ---------------------------------------------------------------------------

// Better Auth's tables, generated by `bunx @better-auth/cli generate`. Its
// `organizations` table IS the tenant boundary from Build Plan §6.1 — the
// organization plugin is pointed at that name, so there is exactly one
// organization table and `session.activeOrganizationId` is the id every
// business table below scopes by.
export * from "./auth-schema";

// Cache of the last successfully verified license (for offline boots).
export const licenseCache = pgTable("license_cache", {
  id: integer("id").primaryKey().default(1), // singleton row
  tier: text("tier").notNull().default("free"),
  modules: jsonb("modules").$type<string[]>().notNull().default([]),
  token: text("token"),
  refreshedAt: timestamp("refreshed_at").defaultNow().notNull(),
});

// ---------------------------------------------------------------------------
// CRM
// ---------------------------------------------------------------------------

export const companies = pgTable(
  "companies",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    website: text("website"),
    /** The company's mark, stored exactly as a contact's avatar is. */
    logoPath: text("logo_path"),
    sector: text("sector"),
    /** Headcount band, not an exact number — nobody knows the exact number. */
    size: integer("size"),
    phone: text("phone"),
    linkedinUrl: text("linkedin_url"),
    address: text("address"),
    city: text("city"),
    state: text("state"),
    postcode: text("postcode"),
    country: text("country"),
    revenue: text("revenue"),
    description: text("description"),
    /**
     * VAT number, EIN, GST/HST number — whatever this company is registered
     * under. Named for the thing rather than one market's word for it, since
     * this product sells into four of them.
     */
    taxIdentifier: text("tax_identifier"),
    /**
     * Anywhere else this company exists: their careers page, a news piece, a
     * Companies House record. Free-form because there is no knowing in
     * advance what somebody wants to keep a link to.
     */
    contextLinks: jsonb("context_links").$type<string[]>().default([]),
    /** Whose account this is. A platform user, not a separate sales record. */
    ownerId: text("owner_id"),
    /** Whatever this business decided to keep, per `crm_settings.custom_fields`. */
    customValues: jsonb("custom_values")
      .$type<Record<string, string | number | boolean | null>>()
      .default({}),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("companies_org_idx").on(t.organizationId)],
);

export const contacts = pgTable(
  "contacts",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    companyId: uuid("company_id"),
    kind: text("kind").notNull().default("customer"), // customer|lead|supplier
    /**
     * The display name, always written as first + last.
     *
     * Kept rather than replaced: invoices, quotes and the customer portal all
     * read it, and a CRM rework is no reason to go and change how an invoice
     * addresses somebody. The CRM writes all three together.
     */
    name: text("name").notNull(),
    firstName: text("first_name"),
    lastName: text("last_name"),
    title: text("title"),
    /**
     * A face against the name.
     *
     * The stored path of a resized WebP under the data directory, never the
     * bytes and never the uploaded filename — same rule the note attachments
     * follow, for the same reasons.
     */
    avatarPath: text("avatar_path"),
    linkedinUrl: text("linkedin_url"),
    /** Whose contact this is — a platform user. */
    ownerId: text("owner_id"),
    /**
     * The first email and phone, kept as plain columns.
     *
     * Everything that already invoices or emails a contact reads these, and a
     * business almost always has one address that matters. The labelled lists
     * below are the rest of them.
     */
    email: text("email"),
    phone: text("phone"),
    /**
     * Every way to reach them: [{ label: "work", value: "..." }].
     *
     * A contact with two numbers and nowhere to put the second is the gap
     * people notice first. A list rather than more columns, because the number
     * of them is not knowable in advance.
     */
    emails: jsonb("emails").$type<{ label: string; value: string }[]>(),
    phones: jsonb("phones").$type<{ label: string; value: string }[]>(),
    /**
     * How warm this relationship is: cold, warm, hot, in-contract.
     *
     * The labels are configurable per organization — a business that sells
     * retainers and one that sells jobs do not describe a customer the same
     * way — so this is the stored value, not a display string.
     */
    status: text("status").notNull().default("cold"),
    /**
     * Everything about them that is not a field: how they were met, who
     * introduced them, what they care about.
     *
     * The one place a CRM earns its keep over a spreadsheet, so it is a
     * first-class column rather than a note somebody has to go and find.
     */
    background: text("background"),
    /** When they first appeared, and when anybody last dealt with them. */
    firstSeenAt: timestamp("first_seen_at").defaultNow(),
    lastSeenAt: timestamp("last_seen_at").defaultNow(),
    /**
     * Whether they agreed to be emailed things they did not ask for.
     *
     * Its own column and not a tag: consent to marketing is a legal position
     * in every market this product sells into, and a tag somebody can delete
     * by accident is not where that belongs.
     */
    hasNewsletter: boolean("has_newsletter").notNull().default(false),
    /** Used only to pick the right placeholder face, never for anything else. */
    gender: text("gender"),
    /**
     * Nothing writes this, and as of 2026-09-05 nothing reads it.
     *
     * It was read by one route — a customer portal listing a signed-in
     * contact's own invoices — which therefore always returned an empty list,
     * and which no screen ever called. The route is gone. The column and its
     * index stay one release, as every dropped column here does, in case an
     * instance is holding data somebody put there by hand.
     *
     * The portal that customers actually use is the token one at
     * `/portal/:token`, which needs no account and does not touch this.
     */
    portalUserId: text("portal_user_id"),
    /**
     * Bearer of this customer's portal link.
     *
     * A token rather than an account: the people being invoiced are customers
     * of a small business, and asking them to create a login to look at a bill
     * is how a bill goes unread. Null until someone asks for the link;
     * reissuing revokes the old one.
     */
    portalToken: text("portal_token"),
    /** Whatever this business decided to keep, per `crm_settings.custom_fields`. */
    customValues: jsonb("custom_values")
      .$type<Record<string, string | number | boolean | null>>()
      .default({}),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("contacts_org_idx").on(t.organizationId),
    index("contacts_portal_user_idx").on(t.portalUserId),
    // The list's default order, and the column four of its filters read.
    index("contacts_last_seen_idx").on(t.organizationId, t.lastSeenAt),
  ],
);

export const deals = pgTable(
  "deals",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    companyId: uuid("company_id"),
    /**
     * Everyone involved, not one person.
     *
     * A deal at a company of any size has several people attached to it, and
     * the previous single `contactId` meant recording one and losing the rest.
     */
    contactIds: jsonb("contact_ids").$type<string[]>().default([]),
    category: text("category"),
    stage: text("stage").notNull().default("opportunity"),
    description: text("description"),
    amountCents: integer("amount_cents").notNull().default(0),
    expectedCloseOn: date("expected_close_on"),
    /**
     * Where the card sits in its column.
     *
     * A kanban that reorders itself on every load is not a kanban — people
     * arrange the column to mean something, and that arrangement has to
     * survive a refresh.
     */
    position: integer("position").notNull().default(0),
    /** Filed away rather than deleted: won and lost deals are the history. */
    archivedAt: timestamp("archived_at"),
    /**
     * When this deal was actually won or lost.
     *
     * Not `updatedAt`, which is what the won-and-lost chart used to read and
     * which moves every time anybody touches the record — so adding a note to
     * a deal won in June silently moved it into the current month and the
     * chart of six months quietly rewrote its own history.
     *
     * Set when the stage moves into one this business counts as won or lost,
     * and cleared if it moves back out. Null on an open deal.
     */
    decidedAt: timestamp("decided_at"),
    ownerId: text("owner_id"),
    /**
     * The form submission this came from, when it came from one.
     *
     * Kept so promoting twice returns the same deal rather than making a
     * second — somebody clicking twice should not end up with two identical
     * cards in the same column.
     */
    sourceSubmissionId: uuid("source_submission_id"),
    /** Whatever this business decided to keep, per `crm_settings.custom_fields`. */
    customValues: jsonb("custom_values")
      .$type<Record<string, string | number | boolean | null>>()
      .default({}),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [
    index("deals_org_idx").on(t.organizationId),
    index("deals_stage_idx").on(t.organizationId, t.stage),
  ],
);

/**
 * Notes against a contact or a deal, with files.
 *
 * One table rather than Atomic's two, matching how `taggables` already works
 * here — the shape is identical and two tables would mean two of every query.
 */
export const notes = pgTable(
  "notes",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    entityType: text("entity_type").notNull(), // "contact" | "deal"
    entityId: uuid("entity_id").notNull(),
    text: text("text").notNull(),
    /**
     * Files kept on disk under the data directory, recorded here.
     *
     * The path, not the bytes: a quote or a signed job sheet in a database
     * column bloats every backup and every query that touches the row.
     */
    attachments: jsonb("attachments")
      .$type<{ name: string; path: string; size: number; type: string }[]>()
      .default([]),
    authorId: text("author_id"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("notes_org_idx").on(t.organizationId),
    index("notes_entity_idx").on(t.entityType, t.entityId),
  ],
);

export const activities = pgTable(
  "activities",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    contactId: uuid("contact_id"),
    dealId: uuid("deal_id"),
    type: text("type").notNull(), // call|email|note|meeting
    body: text("body"),
    occurredAt: timestamp("occurred_at").defaultNow().notNull(),
  },
  (t) => [index("activities_org_idx").on(t.organizationId)],
);

export const tasks = pgTable(
  "tasks",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    title: text("title").notNull(),
    /** What kind of follow-up: call, email, meeting, other. */
    type: text("type"),
    /**
     * Who it is about. A task with no contact is a to-do list item; a task
     * with one is the follow-up that stops a deal going quiet, which is the
     * whole reason a CRM has tasks at all.
     */
    contactId: uuid("contact_id"),
    dealId: uuid("deal_id"),
    /**
     * Or the company, when there is no one person it belongs to.
     *
     * "Renew the retainer" is owed by the account, not by whichever contact
     * happened to answer the phone last time — and filing it against a person
     * means it disappears when that person leaves. A task has one subject or
     * none; this is the third thing it can be.
     */
    companyId: uuid("company_id"),
    /**
     * What the task actually involves, beyond its one-line title.
     *
     * "Call Dave" is the title; "he wants the revised figure for the second
     * unit before he signs" is why the call is worth anything.
     */
    description: text("description"),
    dueAt: timestamp("due_at"),
    assigneeId: text("assignee_id"),
    done: boolean("done").notNull().default(false),
    /** When it was ticked off, so a finished task can still be read in order. */
    doneAt: timestamp("done_at"),
  },
  (t) => [index("tasks_org_idx").on(t.organizationId)],
);

/**
 * What a business calls its own pipeline.
 *
 * The stages were hard-coded in the browser, which meant every business ran
 * somebody else's sales process. A roofer's pipeline is quote → measured →
 * scheduled; a consultancy's is nothing like it, and neither is served by a
 * list a developer picked.
 *
 * One row per organization. Absent means the defaults, so an instance that
 * never opens CRM Settings behaves exactly as it did.
 */
export const crmSettings = pgTable("crm_settings", {
  id: uuid("id").defaultRandom().primaryKey(),
  organizationId: text("organization_id").notNull().unique(),
  /**
   * Ordered. The order is the board, left to right, so it is data rather than
   * a sort somebody has to reproduce in three places.
   */
  dealStages: jsonb("deal_stages").$type<{ id: string; label: string }[]>(),
  /** Call, email, meeting — whatever this business actually does. */
  taskTypes: jsonb("task_types").$type<string[]>(),
  /**
   * Which stages mean the deal was won.
   *
   * Data, not a hard-coded "won": a business whose last stage is "Installed"
   * still needs its dashboard to count that as money in, and the chart of
   * won against lost is unanswerable without knowing which is which.
   */
  wonStages: jsonb("won_stages").$type<string[]>(),
  /** And which mean it was lost, for the same reason. */
  lostStages: jsonb("lost_stages").$type<string[]>(),
  /** The industries this business sells into, for the company record. */
  companySectors: jsonb("company_sectors").$type<string[]>(),
  /** What kinds of work a deal can be: install, retainer, one-off. */
  dealCategories: jsonb("deal_categories").$type<string[]>(),
  /**
   * How warm a contact is, with the colour the list draws it in. Ordered
   * coldest to warmest, because that order is what the filter offers.
   */
  contactStatuses:
    jsonb("contact_statuses").$type<
      { id: string; label: string; color: string }[]
    >(),
  /**
   * Capturing email into the CRM.
   *
   * A business CCs an address on the mail it already sends, and the message
   * lands on the customer's record as a note. The secret is the whole
   * credential on an unauthenticated endpoint, so it is compared in constant
   * time and is null until somebody deliberately turns this on.
   */
  /**
   * The extra fields this business keeps, beyond the ones every CRM has.
   *
   * A definition, not a column: a plumber wants "boiler model" on a contact
   * and a studio wants "brand guidelines link", and neither is worth a
   * migration. Values live in `custom_values` on the record itself.
   */
  customFields:
    jsonb("custom_fields").$type<
      {
        id: string;
        label: string;
        type: "text" | "number" | "date" | "select" | "checkbox";
        options?: string[];
        /**
         * A string, not a closed union.
         *
         * The rules for these live in the module SDK and are shared with the
         * accounting module, which has subjects of its own. The column holds
         * whatever the owning module validated; narrowing it here would make
         * the shared parser unusable from anywhere but the CRM.
         */
        appliesTo: string;
      }[]
    >(),
  inboundSecret: text("inbound_secret"),
  /** The address being CC'd, so the screen can show what to type. */
  inboundAddress: text("inbound_address"),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

export const tags = pgTable(
  "tags",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    /** Tags are scanned, not read. Without colour they are just more text. */
    color: text("color").notNull().default("#94a3b8"),
  },
  (t) => [index("tags_org_idx").on(t.organizationId)],
);

export const taggables = pgTable(
  "taggables",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    tagId: uuid("tag_id").notNull(),
    entityType: text("entity_type").notNull(), // "contact" | "deal"
    entityId: uuid("entity_id").notNull(),
  },
  (t) => [index("taggables_entity_idx").on(t.entityType, t.entityId)],
);

// ---------------------------------------------------------------------------
// Invoicing — money is integer cents, tax is basis points
// ---------------------------------------------------------------------------

export const quotes = pgTable(
  "quotes",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    contactId: uuid("contact_id"),
    number: text("number").notNull(),
    status: text("status").notNull().default("draft"), // draft|sent|accepted|declined|expired
    currency: text("currency").notNull().default("USD"),
    issueDate: timestamp("issue_date").defaultNow().notNull(),
    /** After this, the price is no longer promised. */
    validUntil: timestamp("valid_until"),
    subtotalCents: integer("subtotal_cents").notNull().default(0),
    /** A reduction on the whole document: percent (basis points) or an amount. */
    discountType: text("discount_type"), // percent|amount
    discountValue: integer("discount_value").notNull().default(0),
    discountCents: integer("discount_cents").notNull().default(0),
    taxCents: integer("tax_cents").notNull().default(0),
    totalCents: integer("total_cents").notNull().default(0),
    notes: text("notes"),
    /**
     * The link a customer opens, and whether it is live.
     *
     * A token rather than an account: the person being quoted is a customer of
     * a small business, and asking them to register to read a price is how a
     * quote goes unread.
     */
    shareToken: text("share_token"),
    published: boolean("published").notNull().default(false),
    /** When they first opened it. The read receipt the reference gets right. */
    firstViewedAt: timestamp("first_viewed_at"),
    lastViewedAt: timestamp("last_viewed_at"),
    viewCount: integer("view_count").notNull().default(0),
    /** Which template the PDF is rendered with. Null means the default. */
    templateId: uuid("template_id"),
    /** Set once it has become an invoice, so converting twice cannot happen. */
    convertedInvoiceId: uuid("converted_invoice_id"),
    /**
     * The deal this was quoted for, when it came from one.
     *
     * Not a uniqueness constraint: re-quoting after the customer asks for a
     * change is ordinary, and a business that cannot do it goes back to the
     * word processor. What this buys is the deal being able to show what was
     * quoted against it, so nobody raises the second one blind.
     */
    dealId: uuid("deal_id"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
    /**
     * Filed away rather than erased.
     *
     * A quote somebody sent is a thing that happened, and a business that
     * deletes one loses the only record of what it offered.
     */
    deletedAt: timestamp("deleted_at"),
  },
  (t) => [
    index("quotes_org_idx").on(t.organizationId),
    uniqueIndex("quotes_share_token_idx").on(t.shareToken),
  ],
);

/**
 * Billing a quote in stages.
 *
 * A large job is agreed once and invoiced three times — a deposit, a stage
 * payment, the balance. Without this the business raises three unrelated
 * invoices and nothing connects them back to what was agreed.
 */
export const quoteInstalments = pgTable(
  "quote_instalments",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    quoteId: uuid("quote_id").notNull(),
    invoiceId: uuid("invoice_id"),
    /** Order on the schedule: 1, 2, 3. */
    seq: integer("seq").notNull(),
    /** Share of the quote, in basis points. 2500 = a quarter. */
    shareBp: integer("share_bp").notNull(),
    label: text("label").notNull(),
    dueDate: timestamp("due_date"),
  },
  (t) => [index("quote_instalments_quote_idx").on(t.quoteId)],
);

export const quoteLines = pgTable(
  "quote_lines",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    quoteId: uuid("quote_id").notNull(),
    /** What was picked from the catalogue, if anything. Kept for reporting. */
    billableItemId: uuid("billable_item_id"),
    description: text("description").notNull(),
    /**
     * Thousandths, not a whole number.
     *
     * "1.5 hours" and "0.25 days" are ordinary lines on a service invoice, and
     * an integer quantity forces the business to fake them in the price.
     */
    quantityMilli: integer("quantity_milli").notNull().default(1000),
    quantity: integer("quantity").notNull().default(1),
    unitPriceCents: integer("unit_price_cents").notNull(),
    /** hour, day, piece — shown beside the quantity. */
    unit: text("unit").notNull().default("piece"),
    /** Which named rate this was charged at, and the rate itself, copied. */
    taxDefinitionId: uuid("tax_definition_id"),
    taxRateBp: integer("tax_rate_bp").notNull().default(0),
    /** The order somebody arranged them in, which has to survive a reload. */
    sortOrder: integer("sort_order").notNull().default(0),
  },
  (t) => [index("quote_lines_quote_idx").on(t.quoteId)],
);

export const invoices = pgTable(
  "invoices",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    contactId: uuid("contact_id"),
    quoteId: uuid("quote_id"), // set when converted from a quote
    number: text("number").notNull(),
    status: text("status").notNull().default("draft"), // draft|open|partial|paid|void
    currency: text("currency").notNull().default("USD"),
    /** invoice | credit_note. A credit note is the same document, negated. */
    kind: text("kind").notNull().default("invoice"),
    /** What this credits or replaces, for a credit note or a re-issue. */
    referenceInvoiceId: uuid("reference_invoice_id"),
    issueDate: timestamp("issue_date").defaultNow().notNull(),
    dueDate: timestamp("due_date"),
    subtotalCents: integer("subtotal_cents").notNull().default(0),
    /** A reduction on the whole document: percent (basis points) or an amount. */
    discountType: text("discount_type"), // percent|amount
    discountValue: integer("discount_value").notNull().default(0),
    discountCents: integer("discount_cents").notNull().default(0),
    taxCents: integer("tax_cents").notNull().default(0),
    totalCents: integer("total_cents").notNull().default(0),
    notes: text("notes"),
    /** "30 days net", or whatever this business writes on its documents. */
    paymentTerms: text("payment_terms"),
    /**
     * Pay early and pay less — Skonto, in the German the practice comes from.
     *
     * Three fields rather than a computed amount: the offer is a percentage or
     * a sum, good for so many days from issue, and what it is worth depends on
     * the total at the moment somebody pays. Storing the saving would freeze it
     * against a document that can still be edited while it is a draft.
     */
    earlyDiscountType: text("early_discount_type"), // percent|amount
    earlyDiscountValue: integer("early_discount_value").notNull().default(0),
    earlyDiscountDays: integer("early_discount_days"),
    /**
     * What was actually given up, once somebody took the offer.
     *
     * Recorded because the invoice is then settled for less than it asks for,
     * and "paid" has to mean paid: without this the balance would sit at the
     * saving for ever, and every aging report would carry a debt nobody owes.
     */
    earlyDiscountTakenCents: integer("early_discount_taken_cents")
      .notNull()
      .default(0),
    /**
     * What this document's currency was worth when it was raised, in millionths.
     *
     * Stored rather than looked up each time, exactly as a bill stores it: the
     * ledger holds base-currency figures converted at the rate that applied on
     * the day, and a rate re-read later would restate accounts that have
     * already been reported. A million is 1:1, which is what an invoice in the
     * currency the books are kept in gets and what every existing row means.
     */
    rateMicro: integer("rate_micro").notNull().default(1_000_000),
    /**
     * The link a customer opens, and whether it is live.
     *
     * The view counters are the read receipt: a business chasing an unpaid
     * invoice is in a different conversation depending on whether the customer
     * has opened it, and guessing is worse than knowing.
     */
    shareToken: text("share_token"),
    published: boolean("published").notNull().default(false),
    firstViewedAt: timestamp("first_viewed_at"),
    lastViewedAt: timestamp("last_viewed_at"),
    viewCount: integer("view_count").notNull().default(0),
    /** Which template the PDF is rendered with. Null means the default. */
    templateId: uuid("template_id"),
    lastReminderAt: timestamp("last_reminder_at"),
    /** Charged by rule when it went past its date, so it is not re-added. */
    lateFeeCents: integer("late_fee_cents").notNull().default(0),
    lateFeeAppliedAt: timestamp("late_fee_applied_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
    /** Filed away rather than erased: a sent invoice is a thing that happened. */
    deletedAt: timestamp("deleted_at"),
  },
  (t) => [
    index("invoices_org_idx").on(t.organizationId),
    index("invoices_contact_idx").on(t.contactId),
    uniqueIndex("invoices_share_token_idx").on(t.shareToken),
  ],
);

/**
 * The tax on a document, banded by rate.
 *
 * Kept alongside the per-line rate rather than derived from it. Two reasons:
 * a document's tax has to stay what it was when it was issued, even if a rate
 * changes afterwards; and this is the only shape that answers "how much was
 * taxed at each rate, under which category" without recomputing it — which is
 * exactly what an EN 16931 e-invoice has to state.
 */
export const documentTaxes = pgTable(
  "document_taxes",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** "invoice" | "quote" */
    documentType: text("document_type").notNull(),
    documentId: uuid("document_id").notNull(),
    taxDefinitionId: uuid("tax_definition_id"),
    /** Copied, not joined: the name on a document must not change later. */
    name: text("name").notNull(),
    rateBp: integer("rate_bp").notNull(),
    /**
     * EN 16931 category: S standard, Z zero-rated, E exempt, AE reverse
     * charge, G export, O outside scope. Stored now so e-invoicing needs no
     * migration when it comes.
     */
    categoryCode: text("category_code").notNull().default("S"),
    taxableCents: integer("taxable_cents").notNull().default(0),
    taxCents: integer("tax_cents").notNull().default(0),
  },
  (t) => [
    index("document_taxes_doc_idx").on(t.documentType, t.documentId),
    index("document_taxes_org_idx").on(t.organizationId),
  ],
);

/**
 * The tax rates a business actually charges, named.
 *
 * A rate typed into a line is a rate somebody will mistype. Naming them once —
 * "VAT 20%", "GST/HST 13%", "Zero-rated" — is what makes a tax summary report
 * possible at all, and what an e-invoice needs to state a category for.
 */
export const taxDefinitions = pgTable(
  "tax_definitions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    rateBp: integer("rate_bp").notNull(),
    categoryCode: text("category_code").notNull().default("S"),
    description: text("description"),
    isDefault: boolean("is_default").notNull().default(false),
    active: boolean("active").notNull().default(true),
    /** Whether it is charged on sales, on purchases, or on both. */
    appliesTo: text("applies_to").notNull().default("both"), // sales|purchases|both
    /**
     * Charged on the running total including other taxes, rather than on the
     * net. Quebec's QST was compound until 2013 and the shape has to exist for
     * the provinces that still stack.
     */
    compound: boolean("compound").notNull().default(false),
    /**
     * Deducted from what is paid rather than added to what is owed.
     *
     * A withholding tax on a supplier's bill means the business pays the
     * supplier less and the difference to the tax authority — which is a
     * different posting from a tax that increases the bill.
     */
    withholding: boolean("withholding").notNull().default(false),
    /**
     * Whether tax paid on a purchase comes back.
     *
     * VAT and GST/HST do: the business reclaims what it paid its suppliers, so
     * the tax on a bill is a debit against what it owes the authority rather
     * than a cost. US sales tax does not — it is part of what the thing cost,
     * and posting it as recoverable would overstate both the expense claim and
     * the refund.
     */
    recoverable: boolean("recoverable").notNull().default(true),
    /** us|ca|uk|eu — the four markets Sentrello sells into, and no others. */
    regime: text("regime"),
    /** "CA-QC", "TX-Austin", or whatever the rate is actually tied to. */
    jurisdiction: text("jurisdiction"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("tax_definitions_org_idx").on(t.organizationId)],
);

/**
 * What a business sells, so a line is picked rather than retyped.
 *
 * Deliberately not the Shop's products. Shop is a paid module for selling to
 * the public, with variants, stock and delivery; this is a list of things to
 * put on an invoice. A business with both keeps one catalogue in the Shop and
 * uses this for the services it bills for.
 */
export const billableItems = pgTable(
  "billable_items",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    description: text("description"),
    sku: text("sku"),
    unitPriceCents: integer("unit_price_cents").notNull().default(0),
    /** hour, day, piece, km — whatever this business bills in. */
    unit: text("unit").notNull().default("piece"),
    /** service | product */
    kind: text("kind").notNull().default("service"),
    /**
     * What makes an item a plan: how often somebody is billed for it.
     *
     * Null is everything sold once. A value — monthly, yearly — makes the same
     * row a subscription plan, priced and taxed exactly as it would be on a
     * one-off invoice, because it is the same thing being sold on a repeat.
     * A separate plans table would have been a second catalogue with its own
     * prices, and two answers to what a thing costs.
     */
    billingInterval: text("billing_interval"),
    /** Every N of those: "every 3 months" is one plan, not three. */
    billingIntervalCount: integer("billing_interval_count")
      .notNull()
      .default(1),
    taxDefinitionId: uuid("tax_definition_id"),
    active: boolean("active").notNull().default(true),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("billable_items_org_idx").on(t.organizationId)],
);

/**
 * The document a business puts in front of its customers.
 *
 * Rendered from an editable template rather than a layout compiled into the
 * product: an invoice is the most-seen thing a small business sends, and one
 * that cannot carry their own letterhead is one they will not send.
 */
export const documentTemplates = pgTable(
  "document_templates",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    description: text("description"),
    /**
     * Branding, not markup.
     *
     * The reference stores a HTML body with a template language in it, per template and renders it
     * into the public document page. That page is same-origin with the
     * application, so a stored `<script>` written by anybody with
     * invoicing:update would run with an administrator's session the moment
     * they previewed it — a permission to edit invoice wording turned into a
     * permission to do anything. What a small business actually wants from a
     * template is its logo, its colour and its own wording, so that is what
     * this holds, and every field is escaped on the way out.
     */
    html: text("html"),
    css: text("css"),
    /** Drawn at the head of the document, and in the accent colour. */
    logoPath: text("logo_path"),
    /** A hex colour for headings and rules. Validated before it is stored. */
    accentColor: text("accent_color"),
    /** The business's own wording, above the lines and below the totals. */
    headerNote: text("header_note"),
    footerNote: text("footer_note"),
    /** letter | a4. The US prints one and the EU prints the other. */
    paperSize: text("paper_size").notNull().default("letter"),
    /**
     * Which of the layouts we ship this one uses.
     *
     * classic | modern | compact. A name, not a stylesheet: the CSS behind
     * each is ours, written once and escaped-by-construction, which is how a
     * business gets three genuinely different-looking documents without being
     * able to write markup into the page a customer opens.
     */
    layout: text("layout").notNull().default("classic"),
    /** invoice | quote | statement */
    appliesTo: text("applies_to").notNull().default("invoice"),
    isDefault: boolean("is_default").notNull().default(false),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [index("document_templates_org_idx").on(t.organizationId)],
);

/**
 * How this business bills, beyond any one document.
 *
 * One row per organization, absent meaning the defaults — the same shape the
 * CRM's settings use, so an instance that never opens the screen behaves
 * exactly as it did before the table existed.
 */
/**
 * When the books were last closed.
 *
 * Everything on or before `closedThrough` is history: a business that has filed
 * a return, given figures to an accountant or simply agreed last quarter is
 * done needs those numbers to stay what they were. Nothing here prevented that
 * — `postJournalEntry` accepted any `postedAt`, and payments have always posted
 * on the date money arrived — so anybody with permission could change a month
 * that had already been reported on, and nothing would say so.
 *
 * Null means no lock, which is what every existing instance gets: a business
 * that has never closed a period must not have one closed for it by an upgrade.
 *
 * Enforced inside `postJournalEntry` rather than in the modules that call it,
 * because the modules are the part that keeps growing. A rule that lives in one
 * caller is a rule the next module has to remember.
 */
/**
 * Whether this business is running under HIPAA, and what that switches on.
 *
 * HIPAA is not a mode software can grant. It is a programme a business runs —
 * risk assessments, workforce training, business associate agreements, a
 * breach response plan — and a vendor claiming to make anybody compliant by
 * flipping a switch is selling something that does not exist.
 *
 * What software can do is provide the controls the Security Rule asks for and
 * refuse to be the weak part. That is what this row does. It is off by default
 * because most businesses running this are not covered entities, and the
 * controls it turns on — a short idle timeout, two-factor for everybody, a log
 * of every *read* of a patient's record — are a real cost to impose on a
 * builder or a florist.
 *
 * The name on the switch matters. It says "HIPAA safeguards", not "HIPAA
 * compliant", because the second is a statement about the business and this
 * table cannot make it true.
 */
export const complianceSettings = pgTable("compliance_settings", {
  id: uuid("id").defaultRandom().primaryKey(),
  organizationId: text("organization_id").notNull().unique(),

  /**
   * Which regimes this business has said apply to it.
   *
   * A t-shirt shop in Texas and the same shop in Berlin are the same software
   * and not the same obligations. Chosen during setup and changed whenever the
   * business changes — an American shop that starts selling into the EU, a
   * practice that stops handling health records. Nothing here is a one-way
   * door.
   */
  regimes: jsonb("regimes").$type<string[]>().notNull().default([]),

  /**
   * Kept as its own column rather than read out of `regimes`.
   *
   * The session guard reads this on every authenticated request. A boolean is
   * an index lookup; a containment test on a json array is not, and this sits
   * on the hot path of the whole product. It is set from the regime list and
   * never independently.
   */
  hipaa: boolean("hipaa").notNull().default(false),

  /**
   * Minutes of inactivity before a session ends. §164.312(a)(2)(iii).
   *
   * Fifteen is the number most covered entities settle on and none of the rule
   * text names one — it says "electronic procedures that terminate an
   * electronic session after a predetermined time of inactivity", and the
   * predetermining is the business's job.
   */
  idleTimeoutMinutes: integer("idle_timeout_minutes").notNull().default(15),

  /**
   * Record every *read* of a record that may hold health information, not only
   * every change. §164.312(b).
   *
   * This is the safeguard most systems lack, and the one an investigation
   * actually asks for: "who looked at this patient's record" is the question
   * after a suspected snooping incident, and a log of writes cannot answer it.
   */
  logReads: boolean("log_reads").notNull().default(true),

  /** Refuse to serve anybody without a second factor. §164.312(d). */
  requireTwoFactor: boolean("require_two_factor").notNull().default(true),

  /**
   * The date the business says it completed its own risk assessment.
   *
   * Stored because §164.308(a)(1)(ii)(A) requires one and the commonest audit
   * finding in small practices is that nobody can produce a date. Nothing
   * enforces it; it is here so the screen can ask.
   */
  riskAssessmentOn: timestamp("risk_assessment_on"),

  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

export const ledgerSettings = pgTable("ledger_settings", {
  id: uuid("id").defaultRandom().primaryKey(),
  organizationId: text("organization_id").notNull().unique(),
  /** The last day of the closed period. Null is no lock at all. */
  closedThrough: timestamp("closed_through"),
  /**
   * The extra fields this business keeps on its bills and its money in and out.
   *
   * A purchase-order number, a job reference, which van the fuel went into.
   * None is worth a migration and every business wants a different one, and a
   * bookkeeper who cannot record the thing their business is asked about keeps
   * a spreadsheet beside the product.
   *
   * The same shape and the same rules as the CRM's — they live in the module
   * SDK — because two copies of the coercion is two places for a number field
   * to start holding the string a browser sent.
   */
  customFields:
    jsonb("custom_fields").$type<
      {
        id: string;
        label: string;
        type: "text" | "number" | "date" | "select" | "checkbox";
        options?: string[];
        appliesTo: string;
      }[]
    >(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

export const invoicingSettings = pgTable("invoicing_settings", {
  id: uuid("id").defaultRandom().primaryKey(),
  organizationId: text("organization_id").notNull().unique(),
  /** How long a customer has to pay, when nobody says otherwise. */
  defaultDueDays: integer("default_due_days").notNull().default(30),
  /** Printed at the foot of every document that does not override it. */
  defaultPaymentTerms: text("default_payment_terms"),
  /**
   * The terms offered on the form, and what each one means in days.
   *
   * A list rather than a free-text box: "30 days net", "Net 30" and "net 30
   * days" are one arrangement typed three ways, and none of them tells the
   * form what the due date should be. Picking one here fills the date in.
   * A business can still type something else — the field keeps its custom
   * option — but the common cases are one press.
   */
  paymentTermOptions: jsonb("payment_term_options")
    .$type<{ label: string; days: number }[]>()
    .notNull()
    .default([
      { label: "Due on receipt", days: 0 },
      { label: "Net 7", days: 7 },
      { label: "Net 14", days: 14 },
      { label: "Net 30", days: 30 },
      { label: "Net 60", days: 60 },
    ]),
  /**
   * What a line is sold by.
   *
   * Typed free-hand these become "hour", "hours", "hr" and "Hrs" on four
   * invoices from the same business. The list is editable, because a business
   * that sells by the cubic yard needs the cubic yard.
   */
  units: jsonb("units")
    .$type<string[]>()
    .notNull()
    .default(["piece", "hour", "day", "week", "month", "kg", "m", "lump sum"]),
  defaultTemplateId: uuid("default_template_id"),
  /**
   * What being late costs: a percentage of the balance, or a flat amount.
   *
   * Off unless a business turns it on. A late fee applied by default is a
   * charge somebody did not agree to, and the first they would know is a
   * customer asking why the figure changed.
   */
  lateFeeType: text("late_fee_type"), // percent|amount
  lateFeeValue: integer("late_fee_value").notNull().default(0),
  /**
   * Days past the due date before it applies.
   *
   * A fee charged the morning after is a fee charged for a payment already in
   * the post. Grace is what makes the rule survive contact with customers.
   */
  lateFeeGraceDays: integer("late_fee_grace_days").notNull().default(7),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

/**
 * When to chase, and what to say.
 *
 * Offsets from the due date, negative before and positive after, so one table
 * covers "a nudge three days before" and "a firmer note fourteen days after".
 */
export const reminderRules = pgTable(
  "reminder_rules",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    /** Days from the due date. Negative is before it. */
    daysOffset: integer("days_offset").notNull(),
    subject: text("subject").notNull(),
    body: text("body").notNull(),
    active: boolean("active").notNull().default(false),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("reminder_rules_org_idx").on(t.organizationId)],
);

/**
 * What was sent, so nobody is chased twice for the same thing.
 *
 * The reference learned this the same way everyone does: a scheduler that
 * reruns, or a clock that moves, and a customer gets the same firm letter four
 * times in a morning.
 */
export const reminderLog = pgTable(
  "reminder_log",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    invoiceId: uuid("invoice_id").notNull(),
    ruleId: uuid("rule_id"),
    sentAt: timestamp("sent_at").defaultNow().notNull(),
    sentTo: text("sent_to"),
  },
  (t) => [
    index("reminder_log_invoice_idx").on(t.invoiceId),
    // One rule fires once per invoice, enforced rather than remembered.
    uniqueIndex("reminder_log_once_idx").on(t.invoiceId, t.ruleId),
  ],
);

export const invoiceLines = pgTable(
  "invoice_lines",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    invoiceId: uuid("invoice_id").notNull(),
    /** What was picked from the catalogue, if anything. Kept for reporting. */
    billableItemId: uuid("billable_item_id"),
    description: text("description").notNull(),
    /**
     * Thousandths, not a whole number.
     *
     * "1.5 hours" and "0.25 days" are ordinary lines on a service invoice, and
     * an integer quantity forces the business to fake them in the price.
     */
    quantityMilli: integer("quantity_milli").notNull().default(1000),
    quantity: integer("quantity").notNull().default(1),
    unitPriceCents: integer("unit_price_cents").notNull(),
    /** hour, day, piece — shown beside the quantity. */
    unit: text("unit").notNull().default("piece"),
    /** Which named rate this was charged at, and the rate itself, copied. */
    taxDefinitionId: uuid("tax_definition_id"),
    taxRateBp: integer("tax_rate_bp").notNull().default(0),
    /** The order somebody arranged them in, which has to survive a reload. */
    sortOrder: integer("sort_order").notNull().default(0),
    /**
     * Which invoice this line came from, when several were merged into one.
     *
     * The number as text rather than a foreign key: the customer's copy has to
     * say "INV-0031" beside the work whether or not that invoice still exists,
     * and a merged document that changed its own history when a source was
     * deleted would be a document nobody could reconcile.
     */
    sourceNumber: text("source_number"),
  },
  (t) => [index("invoice_lines_invoice_idx").on(t.invoiceId)],
);

export const payments = pgTable(
  "payments",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    invoiceId: uuid("invoice_id").notNull(),
    amountCents: integer("amount_cents").notNull(), // supports partial payments
    method: text("method").notNull().default("manual"), // manual|stripe|paypal
    gatewayRef: text("gateway_ref"),
    receivedAt: timestamp("received_at").defaultNow().notNull(),
  },
  (t) => [
    index("payments_org_idx").on(t.organizationId),
    index("payments_invoice_idx").on(t.invoiceId),
  ],
);

export const recurringProfiles = pgTable(
  "recurring_profiles",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    contactId: uuid("contact_id").notNull(),
    name: text("name"),
    /** daily | weekly | monthly | quarterly | yearly */
    interval: text("interval").notNull(),
    /** Every N of those. "Every 2 weeks" is one schedule, not two. */
    intervalCount: integer("interval_count").notNull().default(1),
    nextRunAt: timestamp("next_run_at").notNull(),
    /** After this it stops. Null runs until somebody stops it. */
    endsOn: timestamp("ends_on"),
    /**
     * What this profile bills: a document, or a plan.
     *
     * `invoice` repeats a template — the same lines every period, which is how
     * a retainer or a maintenance contract is billed. `subscription` bills a
     * plan from the catalogue at the price the customer agreed to, and carries
     * the lifecycle a subscription has: trials, pauses, and a cancellation
     * that takes effect at the end of a period somebody has already paid for.
     *
     * One table and one scheduler, deliberately. Two would be two things each
     * believing they own the renewal, which is how a customer is billed twice.
     */
    kind: text("kind").notNull().default("invoice"), // invoice | subscription
    /**
     * The invoice this copies.
     *
     * A real draft invoice rather than a blob of JSON: it can be opened,
     * priced and corrected with the same screen as any other, and what the
     * customer will receive is what somebody can actually look at.
     */
    templateInvoiceId: uuid("template_invoice_id"),
    /** The plan being billed, for a subscription. */
    planItemId: uuid("plan_item_id"),
    quantity: integer("quantity").notNull().default(1),
    /**
     * What this customer pays, copied from the plan when they subscribed.
     *
     * Kept on the subscription rather than read from the plan every period: a
     * business that raises its prices has not raised them for the people who
     * signed up last year, and a plan edited on a Tuesday must not silently
     * rebill everybody on Wednesday.
     */
    unitPriceCents: integer("unit_price_cents"),
    taxRateBp: integer("tax_rate_bp").notNull().default(0),
    taxDefinitionId: uuid("tax_definition_id"),
    currency: text("currency").notNull().default("USD"),
    /**
     * Where a subscription stands: trialing | active | paused | cancelled.
     *
     * `active` on its own could not tell a paused subscription from a
     * cancelled one, and they are not the same thing — one resumes, the other
     * is a customer who left.
     */
    status: text("status").notNull().default("active"),
    startedAt: timestamp("started_at"),
    /** Free until this date; the first invoice is raised after it. */
    trialEndsAt: timestamp("trial_ends_at"),
    /**
     * Cancelled, but not yet over.
     *
     * Somebody who cancels in the middle of a month they have paid for keeps
     * it. The subscription stops billing at this date rather than that
     * moment, which is what every customer expects and what avoids a refund.
     */
    cancelAt: timestamp("cancel_at"),
    cancelledAt: timestamp("cancelled_at"),
    /** What this is called by whoever else is involved — a Stripe id, say. */
    externalRef: text("external_ref"),
    templateJson: jsonb("template_json").$type<{ lines: unknown[] }>(),
    /** Whether raising it also sends it. Off by default. */
    autoSend: boolean("auto_send").notNull().default(false),
    generatedCount: integer("generated_count").notNull().default(0),
    lastGeneratedAt: timestamp("last_generated_at"),
    active: boolean("active").notNull().default(true),
  },
  (t) => [index("recurring_profiles_org_idx").on(t.organizationId)],
);

export const creditNotes = pgTable(
  "credit_notes",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    invoiceId: uuid("invoice_id"),
    amountCents: integer("amount_cents").notNull(),
    reason: text("reason"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("credit_notes_org_idx").on(t.organizationId)],
);

// Per-org sequential document numbering (INV-0001). One row per org per kind;
// bumped inside the invoice transaction with SELECT ... FOR UPDATE.
export const documentCounters = pgTable(
  "document_counters",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    kind: text("kind").notNull(), // invoice|quote
    lastNumber: integer("last_number").notNull().default(0),
  },
  (t) => [index("document_counters_org_kind_idx").on(t.organizationId, t.kind)],
);

// ---------------------------------------------------------------------------
// Bookkeeping (double-entry)
// ---------------------------------------------------------------------------

export const accounts = pgTable(
  "accounts",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    code: text("code").notNull(),
    name: text("name").notNull(),
    type: text("type").notNull(), // asset|liability|equity|income|expense
    description: text("description"),
    /**
     * Where this account sits under another.
     *
     * A chart of accounts is a tree in every accountant's head — "Utilities"
     * under "Premises" — even where the codes already imply it. Null is a
     * top-level account, which is every account a business starts with.
     */
    parentId: uuid("parent_id"),
    /**
     * Retired rather than removed.
     *
     * An account with a single posting against it can never be deleted without
     * taking a journal line with it, so the only honest way to stop somebody
     * using it is to hide it from the pickers and leave the history alone.
     */
    archivedAt: timestamp("archived_at"),
    /**
     * A bank account is an asset account with a statement behind it.
     *
     * Kept as columns here rather than as a table of its own: in double-entry
     * the account already exists, and a separate `bank_accounts` table would
     * be a second row that has to be kept in step with the first.
     */
    isBank: boolean("is_bank").notNull().default(false),
    bankName: text("bank_name"),
    /** The last few digits only — enough to recognise, useless if leaked. */
    bankAccountLast4: text("bank_account_last4"),
    /**
     * The provider's own id for the account, where a feed brought it in.
     *
     * How a synced transaction finds the account it belongs to. Matching on
     * the last four digits instead would put two accounts ending 4321 into
     * one, which is a business's savings posted against its current account
     * and a reconciliation nobody can make balance.
     */
    bankProviderReference: text("bank_provider_reference"),
  },
  (t) => [index("accounts_org_idx").on(t.organizationId)],
);

/**
 * Money in and money out, where it did not come from an invoice.
 *
 * The document side of the books: a customer paying cash, a supplier's bill
 * settled at the counter, a bank charge. Invoices and their payments have their
 * own tables because they are documents somebody sends; this is everything
 * else, and both end up in the same journal.
 *
 * Nothing here is the source of truth for a report — the ledger is. A row here
 * exists so the entry can be shown to somebody as the thing they recorded
 * rather than as two lines of double-entry, and so a receipt can hang off it.
 */
export const transactions = pgTable(
  "transactions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    kind: text("kind").notNull(), // income|expense
    /** The income or expense account it is booked to — its category. */
    accountId: uuid("account_id"),
    /** The bank or cash account the money actually moved through. */
    paidThroughAccountId: uuid("paid_through_account_id"),
    /** Who it was with, when that is somebody the CRM knows. */
    contactId: uuid("contact_id"),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull().default("USD"),
    occurredAt: timestamp("occurred_at").defaultNow().notNull(),
    /** A cheque number, a card reference, whatever the statement will say. */
    reference: text("reference"),
    method: text("method"), // cash|bank|card|other
    description: text("description"),
    receiptFileKey: text("receipt_file_key"),
    /** What this business keeps on its own money in and out. */
    customValues: jsonb("custom_values")
      .$type<Record<string, string | number | boolean | null>>()
      .default({}),
    /**
     * When it was undone.
     *
     * Recording a transaction posts to the ledger, and the ledger does not
     * forget: undoing one posts the opposite entry and stamps this, so the
     * books show both what was recorded and that it was corrected.
     */
    reversedAt: timestamp("reversed_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("transactions_org_date_idx").on(t.organizationId, t.occurredAt),
    index("transactions_account_idx").on(t.accountId),
  ],
);

export const journalEntries = pgTable(
  "journal_entries",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    memo: text("memo"),
    source: text("source"), // "invoice:<id>" | "payment:<id>" | "manual"
    /**
     * Who posted it, where a person did.
     *
     * Null for everything a job or a webhook wrote, which is most of the
     * ledger and is correct: a nightly depreciation run is not a person. What
     * this answers is the question an auditor actually asks — who put this
     * figure in the books — for the entries where somebody did.
     */
    createdBy: text("created_by"),
    postedAt: timestamp("posted_at").defaultNow().notNull(),
  },
  (t) => [index("journal_entries_org_idx").on(t.organizationId)],
);

export const journalLines = pgTable(
  "journal_lines",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    entryId: uuid("entry_id").notNull(),
    accountId: uuid("account_id").notNull(),
    debitCents: integer("debit_cents").notNull().default(0),
    creditCents: integer("credit_cents").notNull().default(0),
    /**
     * Which part of the business this line belongs to.
     *
     * On the line and not on the entry: one bill can cover two jobs, and a
     * business that had to split it into two bills to report on them would
     * stop bothering. Both are optional and always will be — most lines belong
     * to the business as a whole, and a figure with no class is not a figure
     * with a mistake in it.
     */
    classId: uuid("class_id"),
    locationId: uuid("location_id"),
  },
  (t) => [
    index("journal_lines_entry_idx").on(t.entryId),
    index("journal_lines_class_idx").on(t.classId),
    index("journal_lines_location_idx").on(t.locationId),
  ],
);

export const expenses = pgTable(
  "expenses",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    accountId: uuid("account_id"),
    amountCents: integer("amount_cents").notNull(),
    vendor: text("vendor"),
    receiptFileKey: text("receipt_file_key"), // storage-adapter key (local by default)
    spentAt: timestamp("spent_at").defaultNow().notNull(),
  },
  (t) => [index("expenses_org_idx").on(t.organizationId)],
);

// ---------------------------------------------------------------------------
// Purchases — the other half of the books
//
// An invoice asks somebody for money; a bill is somebody asking this business
// for money. They are deliberately separate documents rather than one table
// with a direction flag: they are numbered by different people, they age into
// different reports, and a mistake that let one become the other would put a
// supplier's demand into a customer's statement.
// ---------------------------------------------------------------------------

export const bills = pgTable(
  "bills",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** Who sent it — a CRM contact, never a second list of suppliers. */
    vendorId: uuid("vendor_id"),
    /**
     * The supplier's own number, not ours.
     *
     * A bill arrives with a reference already on it, and that reference is what
     * the supplier will quote when they chase. Generating our own would mean
     * two numbers for one document and a phone call to work out which.
     */
    number: text("number"),
    status: text("status").notNull().default("draft"), // draft|open|partial|paid|void
    currency: text("currency").notNull().default("USD"),
    /**
     * What that currency was worth when the bill was approved, in millionths.
     *
     * Stored on the document rather than looked up again: the liability was
     * recorded at this rate, so the same rate has to be used when part of it
     * is paid, or the two entries would not describe the same debt.
     */
    rateMicro: integer("rate_micro").notNull().default(1_000_000),
    billDate: timestamp("bill_date").defaultNow().notNull(),
    dueDate: timestamp("due_date"),
    subtotalCents: integer("subtotal_cents").notNull().default(0),
    taxCents: integer("tax_cents").notNull().default(0),
    totalCents: integer("total_cents").notNull().default(0),
    /** What this business keeps on its own bills — a purchase order, a job. */
    customValues: jsonb("custom_values")
      .$type<Record<string, string | number | boolean | null>>()
      .default({}),
    notes: text("notes"),
    /** The scan of the paper one, which is what an inspection asks for. */
    receiptFileKey: text("receipt_file_key"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
    deletedAt: timestamp("deleted_at"),
  },
  (t) => [
    index("bills_org_idx").on(t.organizationId),
    index("bills_vendor_idx").on(t.vendorId),
  ],
);

export const billLines = pgTable(
  "bill_lines",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    billId: uuid("bill_id").notNull(),
    description: text("description").notNull(),
    /** Thousandths, as everywhere else a quantity can be a fraction. */
    quantityMilli: integer("quantity_milli").notNull().default(1000),
    unitPriceCents: integer("unit_price_cents").notNull(),
    /** Which expense account this line lands in — the line's category. */
    accountId: uuid("account_id"),
    taxDefinitionId: uuid("tax_definition_id"),
    taxRateBp: integer("tax_rate_bp").notNull().default(0),
    /**
     * Which part of the business this line is for.
     *
     * Per line rather than per bill: one invoice from a builders' merchant
     * covers two jobs, and a business forced to split it into two bills to
     * report on them stops bothering.
     */
    classId: uuid("class_id"),
    locationId: uuid("location_id"),
    sortOrder: integer("sort_order").notNull().default(0),
  },
  (t) => [index("bill_lines_bill_idx").on(t.billId)],
);

export const billPayments = pgTable(
  "bill_payments",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    billId: uuid("bill_id").notNull(),
    amountCents: integer("amount_cents").notNull(),
    paidAt: timestamp("paid_at").defaultNow().notNull(),
    method: text("method"),
    reference: text("reference"),
    /**
     * Tax kept back from the supplier and owed to the authority instead.
     *
     * The supplier receives the amount less this; the business owes the
     * difference. Recorded on the payment rather than the bill because it is
     * decided when the money is sent.
     */
    withheldCents: integer("withheld_cents").notNull().default(0),
    /** Which bank or cash account it left. */
    paidThroughAccountId: uuid("paid_through_account_id"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("bill_payments_org_idx").on(t.organizationId),
    index("bill_payments_bill_idx").on(t.billId),
  ],
);

/**
 * Bills that arrive on a schedule.
 *
 * Rent, insurance, the accountant's retainer — the same bill every month, and
 * the business's own reminder that it is due. Each run copies a template bill
 * into a **draft**, never an approved one: a bill is somebody else's claim, the
 * figure often differs from last month's, and posting a liability nobody has
 * looked at is how a business's books fill with amounts it never agreed to.
 */
export const recurringBills = pgTable(
  "recurring_bills",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    vendorId: uuid("vendor_id"),
    name: text("name"),
    /** daily | weekly | monthly | quarterly | yearly */
    interval: text("interval").notNull(),
    /** Every N of those. "Every 2 weeks" is one schedule, not two. */
    intervalCount: integer("interval_count").notNull().default(1),
    nextRunAt: timestamp("next_run_at").notNull(),
    /** After this it stops. Null runs until somebody stops it. */
    endsOn: timestamp("ends_on"),
    /**
     * The bill this copies — a real draft, so it can be opened and corrected
     * with the same screen as any other.
     */
    templateBillId: uuid("template_bill_id").notNull(),
    generatedCount: integer("generated_count").notNull().default(0),
    lastGeneratedAt: timestamp("last_generated_at"),
    active: boolean("active").notNull().default(true),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("recurring_bills_org_idx").on(t.organizationId)],
);

// ---------------------------------------------------------------------------
// Budgets, and what a currency was worth
// ---------------------------------------------------------------------------

export const budgets = pgTable(
  "budgets",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    year: integer("year").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("budgets_org_idx").on(t.organizationId)],
);

export const budgetLines = pgTable(
  "budget_lines",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    budgetId: uuid("budget_id").notNull(),
    accountId: uuid("account_id").notNull(),
    /** 1–12, or 0 for a figure set across the whole year. */
    month: integer("month").notNull().default(0),
    amountCents: integer("amount_cents").notNull().default(0),
  },
  (t) => [index("budget_lines_budget_idx").on(t.budgetId)],
);

/**
 * What a currency was worth on a day, kept rather than fetched.
 *
 * A rate has to be the one that applied when the document was raised, not the
 * one a service returns today — otherwise last year's accounts change every
 * time they are opened. Stored in millionths so a rate like 0.782341 survives
 * without a float.
 */
export const exchangeRates = pgTable(
  "exchange_rates",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    code: text("code").notNull(),
    rateMicro: integer("rate_micro").notNull(),
    asOf: timestamp("as_of").defaultNow().notNull(),
  },
  (t) => [index("exchange_rates_org_code_idx").on(t.organizationId, t.code)],
);

export const bankImports = pgTable(
  "bank_imports",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    filename: text("filename").notNull(),
    importedAt: timestamp("imported_at").defaultNow().notNull(),
  },
  (t) => [index("bank_imports_org_idx").on(t.organizationId)],
);

export const bankTransactions = pgTable(
  "bank_transactions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /**
     * Which statement it arrived on.
     *
     * A live bank feed makes one of these per sync rather than inventing a
     * second kind of row: everything downstream — matching, reconciliation,
     * the screen — already works in terms of an import, and a feed that
     * bypassed it would need all of that written twice.
     */
    importId: uuid("import_id").notNull(),
    date: timestamp("date").notNull(),
    description: text("description"),
    amountCents: integer("amount_cents").notNull(),
    matchedEntryId: uuid("matched_entry_id"), // reconciliation link (Pro)
    /**
     * The bank's own id for it, where a feed supplied one.
     *
     * What makes a sync repeatable: a bank amends a transaction days later —
     * the amount settles, the description gains a merchant name — and without
     * this the amended copy arrives as a second row and the statement no
     * longer balances against itself.
     */
    providerReference: text("provider_reference"),
    /** Which connected account it belongs to, for a feed. */
    bankAccountId: uuid("bank_account_id"),
    /** Whether the bank still calls it provisional. */
    pending: boolean("pending").notNull().default(false),
    /** What the bank guessed it was, kept as a hint for the matcher. */
    category: text("category"),
    /**
     * Which reconciliation cleared it, once one was finished.
     *
     * Reconciled against the ledger and reconciled against the statement are
     * two different claims: the first says a line has been posted, the second
     * says the bank and the books agreed about it on a date somebody signed
     * off. A line carrying this is inside a finished reconciliation and does
     * not move again.
     */
    reconciliationId: uuid("reconciliation_id"),
  },
  (t) => [
    index("bank_transactions_org_idx").on(t.organizationId),
    // One row per transaction per business, however many times a sync runs.
    unique("bank_transactions_provider_ref").on(
      t.organizationId,
      t.providerReference,
    ),
  ],
);

/**
 * Somebody the business pays, and the details it needs to pay them.
 *
 * Kept once and used many times, because the alternative is retyping a sort
 * code and an account number for every payment — which is how money reaches
 * the wrong account. Both numbers are sealed and only their last digits are
 * ever shown: they are enough on their own to take money out of an account in
 * most of the world, and a bookkeeping database is not where they sit readable.
 */
export const payees = pgTable(
  "payees",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** The supplier, where they are one the CRM already knows. */
    contactId: uuid("contact_id"),
    name: text("name").notNull(),
    /** business | personal — the receiving side, which the rail cares about. */
    kind: text("kind").notNull().default("business"),
    /** Sealed. Never returned by any route. */
    accountNumber: text("account_number").notNull(),
    routingNumber: text("routing_number").notNull(),
    accountLast4: text("account_last4"),
    archivedAt: timestamp("archived_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("payees_org_idx").on(t.organizationId)],
);

/**
 * Money actually sent out of the business's bank account.
 *
 * The one thing in this product that cannot be undone by pressing something
 * else. So it is written down before it is sent, carries the key that stops a
 * double press sending twice, and records what the provider said rather than
 * what we hoped — a payment believed to have been made is worse than one that
 * failed loudly.
 */
export const bankPayments = pgTable(
  "bank_payments",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    payeeId: uuid("payee_id").notNull(),
    /** The bill it settles, where it settles one. */
    billId: uuid("bill_id"),
    /** The connection and the account the money leaves. */
    connectionId: uuid("connection_id").notNull(),
    fromAccountReference: text("from_account_reference").notNull(),
    /** The chart account the credit posts to, so the books follow the money. */
    fromLedgerAccountId: uuid("from_ledger_account_id"),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull().default("USD"),
    description: text("description"),
    /**
     * What the caller called this attempt.
     *
     * Two presses of one button are one payment. Held unique per business, so
     * the second attempt finds the first rather than sending again.
     */
    idempotencyKey: text("idempotency_key").notNull(),
    /** draft | pending | posted | failed | cancelled */
    status: text("status").notNull().default("pending"),
    /** The provider's own id for it, once it has one. */
    providerReference: text("provider_reference"),
    expectedAt: timestamp("expected_at"),
    lastError: text("last_error"),
    /** Set once the money is in the books, so it is never posted twice. */
    entryId: uuid("entry_id"),
    /** Which repeating arrangement made it, if any. */
    scheduleId: uuid("schedule_id"),
    createdBy: text("created_by"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    index("bank_payments_org_idx").on(t.organizationId),
    unique("bank_payments_idempotency").on(t.organizationId, t.idempotencyKey),
  ],
);

/**
 * A payment that repeats — the monthly connection, the rent.
 *
 * Held here even when the provider schedules it itself, because a business
 * needs to see what it has standing instructions for without signing in to a
 * bank, and needs to be able to stop one.
 */
export const bankPaymentSchedules = pgTable(
  "bank_payment_schedules",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    payeeId: uuid("payee_id").notNull(),
    connectionId: uuid("connection_id").notNull(),
    fromAccountReference: text("from_account_reference").notNull(),
    fromLedgerAccountId: uuid("from_ledger_account_id"),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull().default("USD"),
    description: text("description"),
    /** week | month | quarter | year */
    every: text("every").notNull(),
    startsOn: timestamp("starts_on").notNull(),
    endsOn: timestamp("ends_on"),
    providerReference: text("provider_reference"),
    active: boolean("active").notNull().default(true),
    lastError: text("last_error"),
    createdBy: text("created_by"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("bank_payment_schedules_org_idx").on(t.organizationId)],
);

/**
 * What a US business has to tell the IRS about who it paid.
 *
 * A business that pays an unincorporated contractor $600 or more in a calendar
 * year files a 1099-NEC for them, and needs three things it does not otherwise
 * keep: the contractor's legal name, their taxpayer identification number, and
 * their address. Getting to January without them means chasing people who have
 * already moved on, which is why every accounting product asks for them when
 * the vendor is set up rather than when the form is due.
 *
 * **Sold into the US, Canada, the UK and the EU** — this is the US one. It is
 * kept as a table of its own rather than as columns on a contact because it is
 * a tax record about a supplier, not information about a person: it has its own
 * retention, its own sensitivity, and only some businesses have any of it.
 *
 * The identification number is sealed, and only its last four digits are kept
 * in the clear. A TIN is a social security number for most sole traders, and a
 * bookkeeping database is not where one should sit readable.
 */
export const contractorTaxDetails = pgTable(
  "contractor_tax_details",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** The supplier, which is a contact the CRM owns. */
    contactId: uuid("contact_id").notNull(),
    /** Whether this business files a 1099 for them at all. */
    reportable: boolean("reportable").notNull().default(true),
    /** The name on the form, which is often not the trading name. */
    legalName: text("legal_name"),
    /** individual | sole-proprietor | partnership | llc | corporation */
    entityType: text("entity_type"),
    /** Sealed. Never returned by any route. */
    taxId: text("tax_id"),
    /** Enough to recognise it on a screen, useless to anybody who reads it. */
    taxIdLast4: text("tax_id_last4"),
    addressLine1: text("address_line1"),
    addressLine2: text("address_line2"),
    city: text("city"),
    region: text("region"),
    postalCode: text("postal_code"),
    country: text("country").notNull().default("US"),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    index("contractor_tax_details_org_idx").on(t.organizationId),
    // One record per supplier per business.
    unique("contractor_tax_details_contact").on(t.organizationId, t.contactId),
  ],
);

/**
 * Which part of the business a figure belongs to.
 *
 * A builder wants to know whether the kitchen job made money. A shop with two
 * branches wants each one's profit and loss separately. Neither is answerable
 * from a chart of accounts: an account says *what* was spent, and this says
 * *which part of the business* spent it — so a business that needs both ends up
 * inventing "Fuel — Branch A" and "Fuel — Branch B" and doubling its chart
 * every time it opens a shop.
 *
 * Two kinds, because they are used together and mean different things. A class
 * is a job, a project, a department, a product line. A location is a branch, a
 * van, a site. The pair is what lets somebody ask "what did the kitchen job
 * cost at the Leeds branch" without a chart of accounts with sixty entries in
 * it.
 */
export const dimensions = pgTable(
  "dimensions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** class | location */
    kind: text("kind").notNull(),
    name: text("name").notNull(),
    /** The business's own short code for it, shown beside the name. */
    code: text("code"),
    /**
     * Retired rather than deleted.
     *
     * A job that ended still has a year of figures posted against it, and
     * deleting it would leave every one of them pointing at nothing.
     */
    archivedAt: timestamp("archived_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("dimensions_org_idx").on(t.organizationId)],
);

/**
 * The supplier's own credit note, which is not a payment.
 *
 * Goods went back, a bill was overcharged, a subscription was refunded part
 * way through. The business owes less than the bill says, and nobody has moved
 * any money — so recording it as a payment makes the bank reconciliation
 * wrong, and recording nothing leaves a liability on the balance sheet that
 * will never be settled and an aged-payables report that says the business is
 * behind on a bill it does not owe.
 *
 * A credit reduces what is owed the moment it is issued, and is then handed
 * out against specific bills as they are settled. Two steps rather than one,
 * because a supplier commonly issues a credit before anybody has decided which
 * bill it comes off — and a credit with nothing to apply it to yet is a
 * perfectly ordinary thing to be holding.
 */
export const vendorCredits = pgTable(
  "vendor_credits",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** The supplier, which is a contact the CRM already owns. */
    vendorId: uuid("vendor_id"),
    /** The supplier's own reference for it, as printed. */
    number: text("number"),
    issuedAt: timestamp("issued_at").notNull().defaultNow(),
    amountCents: integer("amount_cents").notNull(),
    /**
     * Which expense it comes back off.
     *
     * The credit reverses a cost that was recorded, so it has to say which —
     * putting every credit into one bucket would leave a business's fuel
     * costs overstated and a "supplier credits" line nobody can act on.
     */
    expenseAccountId: uuid("expense_account_id").notNull(),
    notes: text("notes"),
    voidedAt: timestamp("voided_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("vendor_credits_org_idx").on(t.organizationId)],
);

/**
 * A credit, or part of one, put against a particular bill.
 *
 * Its own rows rather than a column on the credit: one credit commonly covers
 * several bills, and a business that had to use a credit all at once would
 * either overpay a bill or leave the credit unusable.
 *
 * Nothing is posted to the ledger here. The credit already reduced what is
 * owed when it was issued; this says which bill stops being outstanding, and
 * posting again would take the liability off twice.
 */
export const vendorCreditApplications = pgTable(
  "vendor_credit_applications",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    creditId: uuid("credit_id").notNull(),
    billId: uuid("bill_id").notNull(),
    amountCents: integer("amount_cents").notNull(),
    appliedAt: timestamp("applied_at").notNull().defaultNow(),
  },
  (t) => [
    index("vendor_credit_applications_org_idx").on(t.organizationId),
    index("vendor_credit_applications_bill_idx").on(t.billId),
  ],
);

/**
 * The month the bank and the books agreed, and somebody said so.
 *
 * Matching a line against an invoice says the money has been recorded. It does
 * not say the account is right. A business finds out it is wrong the way every
 * business finds out — a payment that never arrived, a fee nobody recorded, a
 * transaction entered twice — and the only thing that catches all three is
 * adding up what the bank says, adding up what the books say, and refusing to
 * accept a difference.
 *
 * So this is the one place in the module that will not take "close enough".
 * A reconciliation is finished when the difference is zero, and finishing it
 * marks every line inside it as settled on a date somebody signed off. That is
 * what makes the next month's statement start from a figure both sides agree
 * on rather than from a running total that has been drifting since March.
 */
export const bankReconciliations = pgTable(
  "bank_reconciliations",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** The bank account being reconciled — an account with `isBank`. */
    accountId: uuid("account_id").notNull(),
    /** The statement's closing date and closing balance, as printed. */
    statementDate: timestamp("statement_date").notNull(),
    statementBalanceCents: integer("statement_balance_cents").notNull(),
    /**
     * What the last finished reconciliation closed at.
     *
     * Copied in when this one starts rather than looked up later: a business
     * that reconciles March after April needs March to start from February's
     * figure, not from whatever the newest one happens to be.
     */
    openingBalanceCents: integer("opening_balance_cents").notNull().default(0),
    startedAt: timestamp("started_at").notNull().defaultNow(),
    /** Null until the difference came to zero. */
    completedAt: timestamp("completed_at"),
    completedBy: text("completed_by"),
  },
  (t) => [index("bank_reconciliations_org_idx").on(t.organizationId)],
);

/**
 * A van, a laptop, a coffee machine — and the fact that they wear out.
 *
 * A business that buys a £30,000 van has not spent £30,000 this year; it has
 * swapped cash for something worth roughly £30,000 that will be worth nothing
 * in six years. Recording the purchase as an expense makes this year look
 * terrible and the next five look better than they were, which is the
 * difference between books that answer "how are we doing" and books that do
 * not — and, in every market this is sold into, the difference between a
 * return that is right and one that is not.
 *
 * So the cost sits on the balance sheet and a slice of it becomes an expense
 * every month. The slice is the only thing that is difficult: it must add up
 * to exactly the cost less what the thing will be worth at the end, in whole
 * pennies, however many months that is divided into.
 *
 * Three accounts, which is the convention every accountant already knows: the
 * asset itself, an expense for the slice, and a contra-asset that accumulates
 * what has been taken so the original cost stays legible beside it.
 */
export const fixedAssets = pgTable(
  "fixed_assets",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    description: text("description"),
    /** What it cost, which stays on the books until it is disposed of. */
    costCents: integer("cost_cents").notNull(),
    /** What it will be worth at the end; never depreciated past this. */
    salvageCents: integer("salvage_cents").notNull().default(0),
    acquiredOn: timestamp("acquired_on").notNull(),
    /** straight-line | reducing-balance */
    method: text("method").notNull().default("straight-line"),
    /** How long it lasts, in months. Straight-line divides by this. */
    lifeMonths: integer("life_months").notNull(),
    /** The annual rate in basis points, for reducing balance. */
    rateBp: integer("rate_bp"),
    /** Where the three sides of it go. */
    assetAccountId: uuid("asset_account_id").notNull(),
    expenseAccountId: uuid("expense_account_id").notNull(),
    accumulatedAccountId: uuid("accumulated_account_id").notNull(),
    /**
     * The last month depreciation was posted for.
     *
     * Held as the first day of that month. What stops a monthly job posting
     * twice for one month, and what lets a business that started using this in
     * March catch up on January and February in one run.
     */
    depreciatedThrough: timestamp("depreciated_through"),
    disposedOn: timestamp("disposed_on"),
    disposalProceedsCents: integer("disposal_proceeds_cents"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("fixed_assets_org_idx").on(t.organizationId)],
);

/**
 * Categorising the same coffee shop for the two hundredth time.
 *
 * A bank feed brings in everything: the card at the fuel station, the monthly
 * connection, the software subscription, the customer paying by transfer. Some
 * of it settles an invoice or a bill and is reconciled against one. Most of it
 * is an expense that will never have a document, arriving every month with the
 * same words in it, and typing the account against each one by hand is the
 * work that makes people give up on keeping their books.
 *
 * A rule says: when a statement line says this, it belongs in that account.
 *
 * It is also the one thing here that writes to the ledger while nobody is
 * watching, so the rules around it are narrow rather than clever. It matches
 * on the words the bank sent and the direction the money went, and nothing
 * else. It never touches a line somebody has already reconciled. It never
 * touches one the bank still calls provisional, because the amount can still
 * change. Everything it posts carries the rule's id in its source, so a rule
 * that turns out to be wrong can be found and undone rather than hunted for.
 */
export const bankRules = pgTable(
  "bank_rules",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** What the person called it, for the screen and the audit log. */
    name: text("name").notNull(),
    /** contains | starts | equals — on the description the bank sent. */
    matchType: text("match_type").notNull().default("contains"),
    matchText: text("match_text").notNull(),
    /**
     * in | out | any.
     *
     * The same words mean different things in each direction: a transfer to a
     * savings account and one back from it read identically on a statement.
     */
    direction: text("direction").notNull().default("any"),
    /** Optional bounds, in cents, on the size of the transaction. */
    minCents: integer("min_cents"),
    maxCents: integer("max_cents"),
    /** Where the other side of the entry goes. */
    accountId: uuid("account_id").notNull(),
    /** Lower runs first; the first rule that matches is the one that posts. */
    priority: integer("priority").notNull().default(100),
    enabled: boolean("enabled").notNull().default(true),
    /** What it has actually done, which is the question people ask of it. */
    timesApplied: integer("times_applied").notNull().default(0),
    lastAppliedAt: timestamp("last_applied_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("bank_rules_org_idx").on(t.organizationId)],
);

/**
 * What a business pasted in to use a bank provider at all.
 *
 * Separate from the connections themselves because it comes first: the
 * credentials are the business's account with the provider, and one set of
 * them may open several banks. Sealed, and never returned by any route — the
 * screen shows whether they are set and what they can do, never what they are.
 */
export const bankProviderAccounts = pgTable(
  "bank_provider_accounts",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** plaid | teller */
    provider: text("provider").notNull(),
    /** The provider's own client identifier, where it has one. Not secret. */
    clientId: text("client_id"),
    /** Sealed. */
    secret: text("secret").notNull(),
    testMode: boolean("test_mode").notNull().default(true),
    /**
     * Whether this is the one new connections use.
     *
     * A business may hold credentials for both and be part-way through moving
     * from one to the other; something has to say which a new bank goes
     * through, and it is not "the most recently edited".
     */
    isDefault: boolean("is_default").notNull().default(false),
    /** When somebody last proved these work, so a screen can say so. */
    verifiedAt: timestamp("verified_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("bank_provider_accounts_org_idx").on(t.organizationId),
    unique("bank_provider_accounts_one_per_provider").on(
      t.organizationId,
      t.provider,
    ),
  ],
);

/**
 * A bank a business has connected, and permission to read it.
 *
 * The token here is not the business's provider credentials — those live with
 * the other sealed secrets. This is permission to read one set of accounts,
 * which is why disconnecting is a row going away and a call to the provider
 * rather than a key being rotated.
 */
export const bankConnections = pgTable(
  "bank_connections",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** plaid | teller */
    provider: text("provider").notNull(),
    /** What the bank is called, so a screen says Chase and not an item id. */
    institutionName: text("institution_name"),
    /** Sealed. Never returned by any route, in any shape. */
    accessToken: text("access_token").notNull(),
    /**
     * Where the last sync got to.
     *
     * A cursor rather than a date, because a bank posts a transaction days
     * late and "everything since Tuesday" either misses it or fetches the week
     * again every hour.
     */
    cursor: text("cursor"),
    /** Whether these are the provider's sandbox credentials. */
    testMode: boolean("test_mode").notNull().default(false),
    lastSyncedAt: timestamp("last_synced_at"),
    /**
     * What went wrong last time, in the provider's own words.
     *
     * A bank connection that has quietly stopped is worse than one that never
     * worked: the figures look right and are months old. This is what the
     * screen shows so a business can see it needs signing in again.
     */
    lastError: text("last_error"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("bank_connections_org_idx").on(t.organizationId)],
);

// ---------------------------------------------------------------------------
// Embeddable forms
//
// A form is pasted into any external site — the customer's marketing pages, a
// landing page, anywhere — and posts straight to the customer's own instance.
// Submissions never travel through Foothills infrastructure.
// ---------------------------------------------------------------------------

export const forms = pgTable(
  "forms",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    // public identifier, safe to paste into a page's HTML
    key: text("key").notNull().unique(),
    name: text("name").notNull(),
    kind: text("kind").notNull().default("contact"), // contact|quote
    /**
     * Which form a submission came from, in one word.
     *
     * A business with a contact form on every page cannot tell them apart from
     * the fields alone — every one collects a name and an email. The tag is
     * what makes "where did this come from" answerable.
     */
    tag: text("tag"),
    /**
     * Optional look. Kept small on purpose: a colour and a corner radius cover
     * matching a site, and anything more is a stylesheet somebody should own
     * themselves rather than configure in a form builder.
     */
    style: jsonb("style").$type<{
      accent?: string;
      radius?: string;
      font?: string;
    }>(),
    // domains permitted to post; empty means same-origin only
    allowedOrigins: jsonb("allowed_origins")
      .$type<string[]>()
      .notNull()
      .default([]),
    fields: jsonb("fields")
      .$type<
        { name: string; label: string; type: string; required?: boolean }[]
      >()
      .notNull()
      .default([]),
    redirectUrl: text("redirect_url"),
    notifyEmail: text("notify_email"),
    active: boolean("active").notNull().default(true),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("forms_org_idx").on(t.organizationId)],
);

export const formSubmissions = pgTable(
  "form_submissions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    formId: uuid("form_id").notNull(),
    contactId: uuid("contact_id"),
    quoteId: uuid("quote_id"),
    payload: jsonb("payload").$type<Record<string, string>>().notNull(),
    origin: text("origin"),
    userAgent: text("user_agent"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("form_submissions_org_idx").on(t.organizationId),
    index("form_submissions_form_idx").on(t.formId),
  ],
);

/**
 * Roles a business defined for itself.
 *
 * Better Auth's dynamic access control reads this when checking a permission
 * and merges what it finds with the roles compiled in. Written by its own
 * endpoints, never by us — the shape, including permissions being JSON in a
 * text column, is its contract rather than a choice.
 */
export const organizationRole = pgTable(
  "organization_role",
  {
    id: text("id").primaryKey(),
    organizationId: text("organization_id").notNull(),
    role: text("role").notNull(),
    permission: text("permission").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at"),
  },
  (t) => [
    index("organization_role_org_idx").on(t.organizationId),
    index("organization_role_name_idx").on(t.role),
  ],
);

/**
 * What one person chose, on one instance.
 *
 * Keyed rather than columned because the things people set for themselves —
 * a dashboard layout today, a timezone and a landing page next — arrive one at
 * a time and belong to different modules. A column per preference means a
 * migration per preference, and a table per module means several tables that
 * all say "this user picked this".
 *
 * Scoped by organization as well as user: the same person on a second
 * organization is arranging a different business's screen.
 */
export const userPreferences = pgTable(
  "user_preferences",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    userId: text("user_id").notNull(),
    /** Which preference, e.g. "dashboard". Namespaced by whoever owns it. */
    key: text("key").notNull(),
    value: jsonb("value").notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [
    index("user_preferences_org_idx").on(t.organizationId),
    // One row per person per preference. Without this, a double-save leaves
    // two answers to a question that has one.
    uniqueIndex("user_preferences_unique_idx").on(
      t.organizationId,
      t.userId,
      t.key,
    ),
  ],
);

/**
 * Which optional modules a business has actually turned on.
 *
 * Owning a module and using it are different things. Somebody buys Pro with
 * four modules on a Friday and sets up two of them; the other two are theirs,
 * paid for, and should be waiting quietly rather than filling the sidebar with
 * screens nobody has configured. Sentrello's own instance is the first example
 * of it — every module entitled, most not in use yet.
 *
 * A row means a decision was made. No row means nobody has been asked, which
 * for a module the licence has just started granting is the honest state: it
 * appears under Modules with a way to start, and nowhere else.
 */
export const moduleState = pgTable(
  "module_state",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** The module id the loader knows it by — the same string the licence grants. */
    moduleId: text("module_id").notNull(),
    enabled: boolean("enabled").notNull().default(false),
    /** When it was first turned on, which is a thing support gets asked. */
    enabledAt: timestamp("enabled_at"),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [
    index("module_state_org_idx").on(t.organizationId),
    uniqueIndex("module_state_unique_idx").on(t.organizationId, t.moduleId),
  ],
);

/**
 * Who did what to whose account.
 *
 * Resetting somebody's password, revoking their two-factor, changing what
 * they may do, removing them: each of these hands access around, and without
 * a record the only answer to "who did this and when" is nobody's memory.
 * A business with three staff can shrug at that. One with fifteen, or one
 * being asked by an insurer, cannot.
 *
 * Deliberately append-only from the application's side — nothing here offers
 * a way to edit or delete a row, because a log somebody can quietly tidy is
 * not evidence of anything.
 */
export const securityEvents = pgTable(
  "security_events",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /**
     * The person who did it, where there is one.
     *
     * Null for events with no account behind them — a sign-in attempt against
     * an address that does not exist. Kept as an id and a name together: the
     * id is the truth, but a removed member's name would otherwise resolve to
     * nothing and the log would read "somebody did something to somebody"
     * exactly when it matters most.
     */
    actorId: text("actor_id"),
    actorName: text("actor_name"),
    /** The account it was done to, where there is one. */
    subjectId: text("subject_id"),
    subjectName: text("subject_name"),
    action: text("action").notNull(),
    /** Anything worth knowing that is not a person — an old and new role. */
    detail: jsonb("detail").$type<Record<string, unknown>>(),
    at: timestamp("at").defaultNow().notNull(),
  },
  (t) => [
    index("security_events_org_idx").on(t.organizationId),
    index("security_events_at_idx").on(t.at),
    // Serves both the lockout count and the Events screen's filters.
    index("security_events_org_action_at_idx").on(
      t.organizationId,
      t.action,
      t.at,
    ),
  ],
);

/**
 * A group of people who share a job.
 *
 * The reference's idea, and the right one: an administrator does not want to think
 * about permissions one person at a time. "The office" or "the fitters" is how
 * a business already talks about itself, and a new starter joins a group
 * rather than having six checkboxes copied from somebody similar.
 *
 * A group carries roles rather than permissions. Roles are where a permission
 * set is named and reasoned about; a group is who holds them.
 */
/**
 * How this business takes card payments.
 *
 * One connection for the whole instance, not one per module. A business has a
 * Stripe account, not a Stripe account for invoices and another for the shop,
 * and asking somebody to paste the same keys twice is asking them to get one
 * of the two wrong.
 *
 * The keys always belong to the business. Sentrello is never the merchant of
 * record for what a customer sells and never touches their money — our own
 * Stripe account is only for selling Sentrello. Which is also why these are
 * here rather than in the environment: they were pasted into a screen, sealed,
 * and stored per organization and per mode.
 *
 * One row per provider per mode, so a rehearsal in the sandbox cannot take
 * real money and switching to live is switching a row rather than editing a
 * file on a server.
 */
export const paymentAccounts = pgTable(
  "payment_accounts",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    /** stripe | paypal */
    provider: text("provider").notNull(),
    /** test | live */
    mode: text("mode").notNull().default("test"),
    /** The publishable half. Not a secret, and shown as it is. */
    publicKey: text("public_key"),
    /** Sealed. Never returned by any route, in any shape. */
    secretKey: text("secret_key"),
    /** Sealed. What proves a webhook came from the processor. */
    webhookSecret: text("webhook_secret"),
    /** The last four of the secret, so somebody can recognise their own key. */
    secretHint: text("secret_hint"),
    /** Whether this row is the one the business is using now. */
    enabled: boolean("enabled").notNull().default(false),
    /** What the last "test connection" said, and when. */
    lastTestedAt: timestamp("last_tested_at"),
    lastTestOk: boolean("last_test_ok"),
    lastTestMessage: text("last_test_message"),
    /** Who the processor says we are, from the test call. */
    accountLabel: text("account_label"),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [
    index("payment_accounts_org_idx").on(t.organizationId),
    unique("payment_accounts_unique").on(t.organizationId, t.provider, t.mode),
  ],
);

export const userGroups = pgTable(
  "user_groups",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    description: text("description"),
    /** Role names, built-in or one the business defined for itself. */
    roles: jsonb("roles").$type<string[]>().notNull().default([]),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [
    index("user_groups_org_idx").on(t.organizationId),
    // Two groups called "Office" is two groups nobody can tell apart, and the
    // one somebody adds a new starter to is a coin toss.
    unique("user_groups_unique_name").on(t.organizationId, t.name),
  ],
);

export const userGroupMembers = pgTable(
  "user_group_members",
  {
    groupId: uuid("group_id").notNull(),
    userId: text("user_id").notNull(),
    organizationId: text("organization_id").notNull(),
    addedAt: timestamp("added_at").defaultNow().notNull(),
    addedBy: text("added_by"),
  },
  (t) => [
    unique("user_group_members_unique").on(t.groupId, t.userId),
    index("user_group_members_user_idx").on(t.organizationId, t.userId),
  ],
);

/**
 * The rules a business sets for how people get in.
 *
 * One row per organization. The reference calls these required actions and
 * policies; for a business of under twenty people the useful ones are: who
 * must have a second factor, how long a session lasts, and how short a
 * password may be.
 */
export const securityPolicy = pgTable("security_policy", {
  organizationId: text("organization_id").primaryKey(),
  /**
   * Roles that must have two-factor authentication.
   *
   * Empty means nobody is forced. The point of naming roles rather than
   * everybody is that the person who can move money is not the person who
   * clocks in on a shared tablet.
   */
  /**
   * Whether an unverified address may sign in.
   *
   * Off by default and refused unless mail is configured, because a business
   * that cannot send a verification link and requires one has locked itself
   * out of its own software. See `PUT /api/users/policy`.
   */
  requireEmailVerified: boolean("require_email_verified")
    .notNull()
    .default(false),
  requireTwoFactorFor: jsonb("require_two_factor_for")
    .$type<string[]>()
    .notNull()
    .default([]),
  /** How long somebody stays signed in, in days. Null leaves the default. */
  sessionDays: integer("session_days"),
  /** The shortest password this business will accept. */
  minPasswordLength: integer("min_password_length").notNull().default(12),
  /**
   * How many failures in a row lock an account, and for how long.
   *
   * Zero attempts turns it off, for an instance on a private network where
   * the risk is not worth the support call. The lock itself is not stored —
   * it is counted from the events, so nobody is ever locked out without a
   * visible reason.
   */
  lockoutAfterAttempts: integer("lockout_after_attempts").notNull().default(5),
  lockoutMinutes: integer("lockout_minutes").notNull().default(15),
  /**
   * How long the audit log is kept.
   *
   * An instance whose login page faces the internet collects bot attempts
   * indefinitely, and on a small on-premises box an audit table nobody prunes
   * is a disk that fills.
   */
  eventRetentionDays: integer("event_retention_days").notNull().default(365),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});
